'use strict';
(() => {
const bank=window.QUESTIONS, byId=new Map(bank.map(q=>[q.id,q]));
const KEY='younuo-safety-v2';
let state={records:{},stars:[],mode:'sequence',type:'all',judgeAnswer:'all',current:1},saveOK=true;
try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&typeof s==='object'){state.records=s.records&&typeof s.records==='object'?s.records:{};state.stars=Array.isArray(s.stars)?s.stars.filter(id=>byId.has(id)):[];state.mode=['sequence','random','wrong','star'].includes(s.mode)?s.mode:'sequence';state.type=['all','单选题','多选题','判断题'].includes(s.type)?s.type:'all';state.judgeAnswer=['all','A','B'].includes(s.judgeAnswer)?s.judgeAnswer:'all';state.current=byId.has(s.current)?s.current:1;}}catch{saveOK=false;}
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const names={sequence:'顺序练习',random:'随机练习',wrong:'错题复习',star:'我的收藏'};
let queue=[],index=0,chosen=[],response=null,completed=false,toastTimer;
const wrongIds=()=>bank.filter(q=>state.records[q.id]?.correct===false).map(q=>q.id);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveOK=true;}catch{saveOK=false;}document.querySelectorAll('.save-state').forEach(el=>el.textContent=saveOK?'进度保存在此浏览器，换设备不会同步':'无法保存进度，请检查浏览器存储权限');}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2200);}
function shuffle(a){for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function buildQueue(restore=false){queue=bank.filter(q=>(state.type==='all'||q.type===state.type)&&(state.type!=='判断题'||state.judgeAnswer==='all'||q.answer.includes(state.judgeAnswer))&&(state.mode!=='wrong'||state.records[q.id]?.correct===false)&&(state.mode!=='star'||state.stars.includes(q.id))).map(q=>q.id);if(state.mode==='random')shuffle(queue);index=restore&&queue.includes(state.current)?queue.indexOf(state.current):0;loadQuestion();}
function loadQuestion(){chosen=[];response=null;completed=false;if(queue.length)state.current=queue[index];save();render();}
function setMode(mode){state.mode=mode;buildQueue();}
function stats(){let answered=bank.filter(q=>state.records[q.id]);let correct=answered.filter(q=>state.records[q.id].correct).length;$('#answered-stat').textContent=answered.length;$('#correct-stat').textContent=answered.length?Math.round(correct/answered.length*100)+'%':'—';$('#overall-count').textContent=answered.length+' / 300';$('#overall-bar').style.width=answered.length/3+'%';$('#wrong-count').textContent=wrongIds().length;$('#star-count').textContent=state.stars.length;}
function renderGrid(){const root=$('#question-grid');root.innerHTML=queue.map((id,i)=>{let r=state.records[id];return `<button class="grid-button ${r?(r.correct?'correct':'wrong'):''} ${i===index&&!completed?'current':''}" data-index="${i}" aria-label="原题第 ${id} 题，${r?(r.correct?'上次答对':'上次答错'):'未答'}" ${i===index&&!completed?'aria-current="true"':''}>${id}</button>`;}).join('');$('#map-total').textContent=queue.length+' 题';}
function render(){stats();$('#judgment-filter').hidden=state.type!=='判断题';document.querySelectorAll('[data-answer]').forEach(el=>{let active=el.dataset.answer===state.judgeAnswer;el.classList.toggle('active',active);el.setAttribute('aria-pressed',active);});$('#breadcrumb-mode').textContent=names[state.mode];$('#page-title').textContent=({sequence:'把每一道题，练扎实。',random:'换个顺序，再练一次。',wrong:'把薄弱处，变成得分点。',star:'值得再看一遍的题。'})[state.mode];$('#page-description').textContent=({sequence:'答案与解析均来自原始题库，按自己的节奏开始。',random:'随机排列当前题型，选项顺序保持与原题一致。',wrong:'答错的题自动收录，再次答对后移出错题本。',star:'收藏需要反复记忆的题目，随时回来巩固。'})[state.mode];document.querySelectorAll('[data-mode]').forEach(el=>{let active=el.dataset.mode===state.mode;el.classList.toggle('active',active);el.setAttribute('aria-pressed',active)});document.querySelectorAll('[data-type]').forEach(el=>{let active=el.dataset.type===state.type;el.classList.toggle('active',active);el.setAttribute('aria-pressed',active)});$('#reshuffle').hidden=state.mode!=='random';renderGrid();renderQuestion();}
function renderQuestion(){const panel=$('#question-panel');if(!queue.length){const copy=state.mode==='wrong'?['还没有需要复习的错题','答错的题会自动保存在这里。先去练几道题吧。']:state.mode==='star'?['还没有收藏的题目','练习时点一下题目右上角的收藏，就能留在这里。']:['这个题型暂时没有题目','切换题型，继续练习。'];panel.innerHTML=`<div class="empty-state">${icon(state.mode==='star'?'star':'check')}<h2>${copy[0]}</h2><p>${copy[1]}</p><button class="primary-button" data-action="sequence">开始顺序练习 ${icon('arrow')}</button></div>`;return;}
if(completed){let done=queue.filter(id=>state.records[id]);let correct=done.filter(id=>state.records[id].correct).length;panel.innerHTML=`<div class="completion">${icon('check')}<h2>这一组，练习结束。</h2><p>本组共 ${queue.length} 题，已作答 ${done.length} 题。<br>最近一次作答：${correct} 题正确，${done.length-correct} 题错误${queue.length>done.length?'，还有 '+(queue.length-done.length)+' 题未作答':''}。</p><div class="completion-actions"><button class="primary-button" data-action="restart">再练一遍</button><button class="secondary-button" data-action="wrong">复习错题</button>${queue.length>done.length?'<button class="secondary-button" data-action="unanswered">继续未答题</button>':''}</div></div>`;return;}
const q=byId.get(queue[index]),starred=state.stars.includes(q.id),record=state.records[q.id];
panel.innerHTML=`<article class="question-card"><div class="question-body"><div class="question-meta"><span class="type-badge">${q.type}</span><span class="question-number"><strong>${String(index+1).padStart(2,'0')}</strong> / ${queue.length} <span> · 原题 ${q.id}</span></span><button class="star-button ${starred?'selected':''}" data-action="star" aria-pressed="${starred}">${icon('star')}${starred?'已收藏':'收藏'}</button></div><h2 class="question-stem" id="question-stem">${esc(q.stem)}</h2><p class="answer-instruction">${q.type==='多选题'?'选择所有正确答案，多选、少选均不得分':q.type==='判断题'?'判断题目表述是否正确':'请选择一个正确答案'}${record?' · 上次'+(record.correct?'答对':'答错'):''}</p><div class="options" role="group" aria-labelledby="question-stem">${q.options.map(o=>{let selected=chosen.includes(o.key),correct=response&&q.answer.includes(o.key),wrong=response&&selected&&!q.answer.includes(o.key);return `<button class="option ${selected?'selected':''} ${correct?'correct':''} ${wrong?'wrong':''}" data-option="${o.key}" aria-pressed="${selected}" ${response?'disabled':''}><span class="option-key">${o.key}</span><span class="option-text">${esc(o.text)}</span>${response?(correct?'<span class="option-status">正确答案</span>':wrong?'<span class="option-status">你的选择</span>':''):''}</button>`;}).join('')}</div>${response?feedback(q):''}</div><div class="question-footer"><button class="secondary-button" data-action="prev" ${index===0?'disabled':''}>上一题</button><div class="footer-actions">${!response?'<button class="text-button" data-action="reveal">看答案</button>':''}<button class="primary-button" data-action="${response?'next':'submit'}" ${!response&&!chosen.length?'disabled':''}>${response?(index===queue.length-1?'完成练习':'下一题'):'提交答案'}${icon(response?'arrow':'check')}</button></div></div></article>`;
}
function feedback(q){return `<div class="feedback ${response.revealed?'neutral':response.correct?'':'incorrect'}" role="status"><div class="feedback-title">${response.revealed?'参考答案':response.correct?'回答正确，继续保持。':'这道题再记一下。'}</div><p>${!response.revealed?'你的答案：'+chosen.join('、')+'　 · 　':''}正确答案：<strong>${q.answer.join('、')}</strong><br>${q.answer.map(key=>{let o=q.options.find(o=>o.key===key);return `${key}. ${esc(o.text)}`}).join('<br>')}</p><div class="explanation"><p><strong>原题解析</strong><br>${q.explanation?esc(q.explanation):'原题未提供解析。'}</p></div><small>来源：PDF 第 ${q.page} 页 · 原题第 ${q.id} 题${response.revealed?' · 本次查看不计入作答记录':''}</small></div>`;}
function select(key){if(response||completed||!queue.length)return;const q=byId.get(queue[index]);if(!q.options.some(o=>o.key===key))return;if(q.type==='多选题')chosen=chosen.includes(key)?chosen.filter(x=>x!==key):[...chosen,key].sort();else chosen=[key];renderQuestion();const el=document.querySelector(`[data-option="${key}"]`);el?.focus({preventScroll:true});}
function submit(){if(!chosen.length||response||completed)return;let q=byId.get(queue[index]);let correct=[...chosen].sort().join('')===[...q.answer].sort().join('');response={correct};state.records[q.id]={correct,selected:[...chosen],at:Date.now()};save();stats();renderGrid();renderQuestion();}
function move(delta){if(!queue.length)return;if(index+delta>=queue.length){completed=true;renderQuestion();renderGrid();}else if(index+delta>=0){index+=delta;loadQuestion();}if(matchMedia('(max-width:650px)').matches)$('#question-panel').scrollIntoView({behavior:'instant',block:'start'});}
function act(action){if(action==='sequence'){state.type='all';setMode('sequence');return}if(action==='wrong'){state.type='all';setMode('wrong');return}if(action==='restart'){buildQueue();return}if(action==='unanswered'){index=queue.findIndex(id=>!state.records[id]);if(index<0)index=0;loadQuestion();return}if(!queue.length||completed)return;if(action==='submit')submit();if(action==='prev')move(-1);if(action==='next')move(1);if(action==='reveal'){response={revealed:true};renderQuestion();}if(action==='star'){let id=queue[index];if(state.stars.includes(id)){state.stars=state.stars.filter(x=>x!==id);toast('已取消收藏');}else{state.stars.push(id);toast('已加入收藏');}save();stats();renderQuestion();}}
$('#judgment-filter').addEventListener('click',e=>{let b=e.target.closest('[data-answer]');if(b){state.judgeAnswer=b.dataset.answer;buildQueue();}});
$('#modes').addEventListener('click',e=>{let b=e.target.closest('[data-mode]');if(b)setMode(b.dataset.mode)});$('#type-tabs').addEventListener('click',e=>{let b=e.target.closest('[data-type]');if(b){state.type=b.dataset.type;buildQueue();}});$('#reshuffle').addEventListener('click',()=>{buildQueue();toast('已重新打乱题目顺序');});$('#question-panel').addEventListener('click',e=>{const o=e.target.closest('[data-option]'),a=e.target.closest('[data-action]');if(o)select(o.dataset.option);else if(a&&!a.disabled)act(a.dataset.action)});$('#question-grid').addEventListener('click',e=>{let b=e.target.closest('[data-index]');if(b){index=Number(b.dataset.index);loadQuestion();if(matchMedia('(max-width:650px)').matches)$('#question-panel').scrollIntoView({behavior:'instant'});}});
document.addEventListener('keydown',e=>{if(e.altKey||e.ctrlKey||e.metaKey||e.repeat||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;if(/^[1-5]$/.test(e.key)){e.preventDefault();select(String.fromCharCode(64+Number(e.key)));}else if(e.key==='Enter'&&(e.target.tagName!=='BUTTON'||e.target.hasAttribute('data-option'))){e.preventDefault();if(response)move(1);else submit();}else if(e.key==='ArrowLeft'){e.preventDefault();move(-1);}else if(e.key==='ArrowRight'){e.preventDefault();move(1);}});
if(matchMedia('(max-width:650px)').matches)document.querySelector('.question-map').open=false;
buildQueue(true);
})();
